54	/// This function collects newlines to insert after a given Comment span to preserve them.
55	pub fn collect_newlines_after_comment(
56	    comments_context: &CommentsContext,
57	    comment: &Comment,
58	) -> String {
59	    comments_context.unformatted_code()[comment.span().end()..]
60	        .chars()
61	        .take_while(|&c| c.is_whitespace())
62	        .filter(|&c| c == '\n')
63	        .collect()
64	}
