21	    fn format(
22	        &self,
23	        formatted_code: &mut FormattedCode,
24	        formatter: &mut Formatter,
25	    ) -> Result<(), FormatterError> {
26	        // Required for comment formatting
27	        let start_len = formatted_code.len();
28	
29	        write!(formatted_code, "{}", ImplToken::AS_STR)?;
30	        if let Some(generic_params) = &self.generic_params_opt {
