43	        }
44	
45	        let contents = self.contents.get();
46	        if contents.is_empty() {
47	            let range = self.span().into();
48	            Self::open_curly_brace(formatted_code, formatter)?;
49	            if has_comments_in_formatter(formatter, &range) {
50	                formatter.indent();
