26	/// This macro is a wrapper around the fmt_test! macro and simply passes the AST type
27	/// to it.
28	///
29	/// Provide a known good, and then some named test cases that should evaluate to
30	/// that known good. e.g.:
31	/// ```
32	/// # use paste::paste;
33	/// # use prettydiff::{basic::DiffOp, diff_lines};
34	/// # use test_macros::fmt_test_expr; fn main() {
35	///               // test suite name       known good
36	///fmt_test_expr!(field_proj_foobar       "foo.bar.baz.quux",
37	///               // test case name        should format to known good
38	///               intermediate_whitespace  "foo . bar . baz . quux");
39	/// # }
40	/// ```
41	#[macro_export]
42	macro_rules! fmt_test_expr {
43	    ($scope:ident $desired_output:expr, $($name:ident $y:expr),+) =>{
44	        $crate::fmt_test!(sway_ast::Expr, $scope $desired_output,
45	                    $($name $y)+);
46	            };
