49	/// Convenience macro for generating test cases.
50	///
51	/// This macro should be wrapped by another macro, eg. `fmt_test_expr!` that passes
52	/// in a Sway AST type, eg. sway_ast::Expr, and is not meant to be used directly.
53	#[macro_export]
54	macro_rules! fmt_test {
55	    ($ty:expr, $scope:ident $desired_output:expr, $($name:ident $y:expr),+) => {
56	        $crate::fmt_test_inner!($ty, $scope $desired_output,
57	                                $($name $y)+
58	                                ,
59	                                remove_trailing_whitespace format!("{} \n\n\t ", $desired_output).as_str(),
60	                                remove_beginning_whitespace format!("  \n\t{}", $desired_output).as_str(),
61	                                identity $desired_output, /* test return is valid */
62	                                remove_beginning_and_trailing_whitespace format!("  \n\t  {} \n\t   ", $desired_output).as_str()
63	                       );
