25	/// Remove arguments from the expression if the expression is a method call if
26	/// the method is a simple two path call (foo.bar()). This is needed because in
27	/// method calls of two parts they are never broke into multiple lines.
28	/// Arguments however can be broken into multiple lines, and that is handled
29	/// by `write_function_call_arguments`
30	fn remove_arguments_from_expr(expr: Expr) -> Expr {
31	    match expr {
32	        Expr::MethodCall {
33	            target,
34	            dot_token,
35	            path_seg,
36	            contract_args_opt,
37	            args,
38	        } => {
39	            let is_simple_call = matches!(*target, Expr::Path(_));
40	            let target = remove_arguments_from_expr(*target);
41	            Expr::MethodCall {
42	                target: Box::new(target),
43	                dot_token,
44	                path_seg,
45	                contract_args_opt,
46	                args: if is_simple_call {
47	                    Parens::new(
48	                        Punctuated {
49	                            value_separator_pairs: vec![],
50	                            final_value_opt: None,
51	                        },
52	                        Span::dummy(),
53	                    )
54	                } else {
55	                    args
56	                },
57	            }
58	        }
59	        Expr::FieldProjection {
60	            target,
61	            dot_token,
62	            name,
63	        } => {
64	            let target = remove_arguments_from_expr(*target);
65	            Expr::FieldProjection {
66	                target: Box::new(target),
67	                dot_token,
68	                name,
69	            }
70	        }
71	        _ => expr,
72	    }
73	}
