75	fn format_statement(
76	    statement: &Statement,
77	    formatted_code: &mut FormattedCode,
78	    formatter: &mut Formatter,
79	) -> Result<(), FormatterError> {
80	    match statement {
81	        Statement::Let(let_stmt) => let_stmt.format(formatted_code, formatter)?,
82	        Statement::Item(item) => item.format(formatted_code, formatter)?,
83	        Statement::Expr {
84	            expr,
85	            semicolon_token_opt,
86	        } => {
87	            let mut temp_expr = FormattedCode::new();
88	
89	            remove_arguments_from_expr(expr.clone()).format(&mut temp_expr, formatter)?;
90	            if temp_expr.len() > formatter.shape.width_heuristics.chain_width {
91	                let update_expr_new_line = if !matches!(
92	                    expr,
93	                    Expr::MethodCall { .. }
94	                        | Expr::FuncApp { func: _, args: _ }
95	                        | Expr::If(_)
96	                        | Expr::While {
97	                            while_token: _,
98	                            condition: _,
99	                            block: _
100	                        }
101	                ) {
102	                    // Method calls, If, While should not tamper with the
103	                    // expr_new_line because that would be inherited for all
104	                    // statements. That should be applied at the lowest level
105	                    // possible (ideally at the expression level)
106	                    formatter.shape.code_line.expr_new_line
107	                } else if formatter.shape.code_line.expr_new_line {
108	                    // already enabled
109	                    true
110	                } else {
111	                    formatter.shape.code_line.update_expr_new_line(true);
112	                    false
113	                };
114	                // reformat the expression adding a break
115	                expr.format(formatted_code, formatter)?;
116	                formatter
117	                    .shape
118	                    .code_line
119	                    .update_expr_new_line(update_expr_new_line);
120	            } else {
121	                expr.format(formatted_code, formatter)?;
122	            }
123	            if semicolon_token_opt.is_some() {
124	                if formatter.shape.code_line.line_style == LineStyle::Inline {
125	                    write!(formatted_code, "{}", SemicolonToken::AS_STR)?;
126	                } else {
127	                    writeln!(formatted_code, "{}", SemicolonToken::AS_STR)?;
128	                }
129	            }
130	        }
131	        Statement::Error(_, _) => {
132	            return Err(FormatterError::SyntaxError);
133	        }
134	    }
135	
136	    Ok(())
137	}
