7	pub fn with_handler<T>(
8	    run: impl FnOnce(&Handler) -> Result<T, ErrorEmitted>,
9	) -> Result<T, ParseFileError> {
10	    let handler = <_>::default();
11	    let res = run(&handler);
12	    let (errors, _warnings, _infos) = handler.consume();
13	    res.ok()
14	        .filter(|_| errors.is_empty())
15	        .ok_or(ParseFileError(errors))
16	}
17	
18	pub fn parse_file(
19	    src: Source,
20	    experimental: ExperimentalFeatures,
21	) -> Result<Annotated<Module>, ParseFileError> {
22	    with_handler(|h| sway_parse::parse_file(h, src, None, experimental))
23	}
24	
25	pub fn lex(src: Source) -> Result<CommentedTokenStream, ParseFileError> {
26	    let end = src.text.len();
27	    with_handler(|h| sway_parse::lex_commented(h, src, 0, end, &None))
28	}
