30	pub fn parse_format<P: sway_parse::Parse + crate::Format>(
31	    input: &str,
32	    experimental: ExperimentalFeatures,
33	) -> Result<String, FormatterError> {
34	    let parsed = with_handler(|handler| {
35	        let token_stream = sway_parse::lex(handler, input.into(), 0, input.len(), None)?;
36	        sway_parse::Parser::new(handler, &token_stream, experimental).parse::<P>()
37	    })?;
38	
39	    // Allow test cases that include comments.
40	    let mut formatter = Formatter::default();
41	    formatter.with_comments_context(input)?;
42	
43	    let mut buf = <_>::default();
44	    parsed.format(&mut buf, &mut formatter)?;
45	    Ok(buf)
46	}
